-- スタッフ(0097〜0106)の変更対象・依存先の指紋を出す読み取り専用SQL（何も変更しない・1つのSELECT・個人情報なし）。
-- 結果をCSV(列 k,h)で保存し、compare_staff_fingerprint.py で期待値(staff_expected.json の _watch_base)と比較する。
-- ★先頭の version() 行はPGのバージョン確認用（検証DBはPG17。違っていても指紋は関数本文・属性・権限を使うため通常は影響しないが、差異が出たら詳細SQLで確認する）。
select '_version' as k, version() as h
union all
select k, h from (select 'fn:' || p.oid::regprocedure::text as k, md5(p.prosrc || '|' || pg_get_function_arguments(p.oid) || '|' || pg_get_function_result(p.oid) || '|' || p.prokind::text || p.prosecdef || p.provolatile::text || p.proparallel::text || p.proleakproof || p.proisstrict || p.proretset || '|' || (select l.lanname from pg_language l where l.oid = p.prolang) || '|' || pg_get_userbyid(p.proowner) || '|' || coalesce((select string_agg(case when a.grantee = 0 then 'PUBLIC' else pg_get_userbyid(a.grantee) end || '<-' || pg_get_userbyid(a.grantor) || ':' || a.privilege_type || ':' || a.is_grantable, ',' order by case when a.grantee = 0 then 'PUBLIC' else pg_get_userbyid(a.grantee) end, pg_get_userbyid(a.grantor), a.privilege_type) from aclexplode(coalesce(p.proacl, acldefault('f', p.proowner))) a),'') || '|' || coalesce(array_to_string(p.proconfig, ','), '')) as h from pg_proc p where p.pronamespace = 'public'::regnamespace and p.prokind in ('f','p') union all select 'rel:' || c.relname, md5(c.relkind::text || '|' || pg_get_userbyid(c.relowner) || '|' || c.relrowsecurity || c.relforcerowsecurity || '|' || coalesce((select string_agg(case when a.grantee = 0 then 'PUBLIC' else pg_get_userbyid(a.grantee) end || '<-' || pg_get_userbyid(a.grantor) || ':' || a.privilege_type || ':' || a.is_grantable, ',' order by case when a.grantee = 0 then 'PUBLIC' else pg_get_userbyid(a.grantee) end, pg_get_userbyid(a.grantor), a.privilege_type) from aclexplode(coalesce(c.relacl, acldefault('r', c.relowner))) a),'') || '|' || coalesce((select string_agg(a.attname || ':' || format_type(a.atttypid, a.atttypmod) || ':' || a.attnotnull || ':' || coalesce(pg_get_expr(d.adbin, d.adrelid), '') || ':' || a.attidentity::text || a.attgenerated::text, ',' order by a.attnum) from pg_attribute a left join pg_attrdef d on d.adrelid = a.attrelid and d.adnum = a.attnum where a.attrelid = c.oid and a.attnum > 0 and not a.attisdropped), '') || '|' || coalesce((select string_agg(k.conname || ':' || pg_get_constraintdef(k.oid) || ':' || k.convalidated, ',' order by k.conname) from pg_constraint k where k.conrelid = c.oid), '') || '|' || coalesce((select string_agg(i.indexdef, ',' order by i.indexname) from pg_indexes i where i.schemaname = 'public' and i.tablename = c.relname), '') || '|' || coalesce((select string_agg(o.polname || ':' || o.polcmd::text || ':' || o.polpermissive || ':' || coalesce(pg_get_expr(o.polqual, o.polrelid), '') || ':' || coalesce(pg_get_expr(o.polwithcheck, o.polrelid), '') || ':' || (select coalesce(string_agg(case when r = 0 then 'PUBLIC' else pg_get_userbyid(r) end, ',' order by case when r = 0 then 'PUBLIC' else pg_get_userbyid(r) end), '') from unnest(o.polroles) r), ',' order by o.polname) from pg_policy o where o.polrelid = c.oid), '') || '|' || coalesce((select string_agg(t.tgname || ':' || t.tgenabled::text || ':' || pg_get_triggerdef(t.oid), ',' order by t.tgname) from pg_trigger t where t.tgrelid = c.oid and not t.tgisinternal), '')) from pg_class c where c.relnamespace = 'public'::regnamespace and c.relkind in ('r','p','v','m','S','f') union all select 'type:' || t.typname, md5(t.typtype::text || '|' || coalesce((select string_agg(e.enumlabel, ',' order by e.enumsortorder) from pg_enum e where e.enumtypid = t.oid), '')) from pg_type t where t.typnamespace = 'public'::regnamespace and t.typtype = 'e' union all select 'authtrg:' || t.tgname, md5(t.tgenabled::text || pg_get_triggerdef(t.oid)) from pg_trigger t where t.tgrelid = 'auth.users'::regclass and not t.tgisinternal union all select 'deprel:' || c.relname, md5(c.relkind::text || '|' || c.relrowsecurity || c.relforcerowsecurity || '|' || coalesce((select string_agg(case when a.grantee = 0 then 'PUBLIC' else pg_get_userbyid(a.grantee) end || '<-' || pg_get_userbyid(a.grantor) || ':' || a.privilege_type || ':' || a.is_grantable, ',' order by case when a.grantee = 0 then 'PUBLIC' else pg_get_userbyid(a.grantee) end, pg_get_userbyid(a.grantor), a.privilege_type) from aclexplode(coalesce(c.relacl, acldefault('r', c.relowner))) a),'') || '|' || coalesce((select string_agg(a.attname || ':' || format_type(a.atttypid, a.atttypmod) || ':' || a.attnotnull, ',' order by a.attname) from pg_attribute a where a.attrelid = c.oid and a.attnum > 0 and not a.attisdropped), '') || '|' || coalesce((select string_agg(k.conname || ':' || pg_get_constraintdef(k.oid), ',' order by k.conname) from pg_constraint k where k.conrelid = c.oid), '') || '|' || coalesce((select string_agg(o.polname || ':' || o.polcmd::text || ':' || coalesce(pg_get_expr(o.polqual, o.polrelid), '') || ':' || coalesce(pg_get_expr(o.polwithcheck, o.polrelid), ''), ',' order by o.polname) from pg_policy o where o.polrelid = c.oid), '') || '|' || coalesce((select string_agg(t.tgname || ':' || t.tgenabled::text || ':' || pg_get_triggerdef(t.oid), ',' order by t.tgname) from pg_trigger t where t.tgrelid = c.oid and not t.tgisinternal), '')) from pg_class c where c.relnamespace = 'public'::regnamespace and c.relkind in ('r','p','v','m') union all select 'authcol:' || c.relname || '.' || a.attname, md5(format_type(a.atttypid, a.atttypmod)) from pg_class c join pg_attribute a on a.attrelid = c.oid and a.attnum > 0 and not a.attisdropped where c.relnamespace = 'auth'::regnamespace and c.relname in ('users', 'sessions') and c.relkind in ('r','p') union all select 'authfn:' || p.proname, md5(pg_get_function_identity_arguments(p.oid) || '->' || pg_get_function_result(p.oid)) from pg_proc p where p.pronamespace = 'auth'::regnamespace and p.proname in ('uid', 'jwt', 'role') union all select 'role:' || r.rolname, md5(r.rolname) from pg_roles r where r.rolname in ('anon', 'authenticated', 'service_role', 'postgres')) t(k, h) where k = any(array['authcol:sessions.created_at','authcol:sessions.id','authcol:sessions.updated_at','authcol:sessions.user_id','authcol:users.created_at','authcol:users.email','authcol:users.email_confirmed_at','authcol:users.id','authcol:users.last_sign_in_at','authcol:users.raw_user_meta_data','authfn:jwt','authfn:uid','authtrg:on_auth_user_created','deprel:admin_audit_events','deprel:admin_invoices','deprel:admin_message_deliveries','deprel:admin_messages','deprel:admin_threads','deprel:admin_visit_confirmations','deprel:admin_visit_occurrences','deprel:admin_visit_request_events','deprel:admin_visit_requests','deprel:age_disclosure_requests','deprel:feature_pauses','deprel:notifications','deprel:organization_members','deprel:platform_admins','deprel:profiles','deprel:salary_offers','deprel:salon_organizations','deprel:salon_profiles','deprel:salon_store_culture_profiles','deprel:salon_store_profiles','deprel:salon_stores','deprel:scouts','deprel:store_hiring_process_events','deprel:store_hiring_processes','deprel:store_members','deprel:stylist_evidence_documents','deprel:stylist_favorite_salons','deprel:stylist_match_profiles','deprel:stylist_preference_profiles','deprel:stylist_private','deprel:stylist_profiles','deprel:stylist_salon_interests','deprel:user_roles','fn:_admin_axis_problems(jsonb,text[])','fn:_admin_lock_request(uuid,uuid)','fn:_admin_messages_rules()','fn:_admin_request_hash(text,text[])','fn:_admin_salon_access(uuid,uuid,uuid)','fn:_admin_store_culture_state(boolean,text,jsonb)','fn:_admin_thread_visible_to(uuid,uuid)','fn:_admin_visit_transition_ok(text,text)','fn:_cancel_interest_notifications(uuid,uuid,uuid,text)','fn:admin_assign_visit_request(uuid,uuid,timestamp with time zone)','fn:admin_claim_visit_request(text,uuid)','fn:admin_get_thread(uuid)','fn:admin_get_visit_request(uuid)','fn:admin_list_hiring_processes(text,text,timestamp with time zone,timestamp with time zone,uuid,uuid,integer,integer)','fn:admin_list_store_culture_readiness(text,text,uuid,integer,integer)','fn:admin_list_store_interests(text,timestamp with time zone,timestamp with time zone,uuid,uuid,integer,integer)','fn:admin_list_threads(uuid,uuid,uuid,text,integer,integer)','fn:admin_list_visit_requests(text,text,text,uuid,boolean,integer,integer)','fn:admin_post_message(uuid,uuid,text,text)','fn:admin_record_delivery(uuid,text,text)','fn:admin_record_visit_confirmation(uuid,text,text,text,text,timestamp with time zone)','fn:admin_set_thread_status(uuid,text)','fn:admin_update_visit_request(uuid,text,timestamp with time zone,date,text,text,uuid)','fn:assert_store_recruiting_allowed(uuid)','fn:calculate_match_axes(uuid,uuid)','fn:calculate_match_axes_by_store(uuid,uuid)','fn:calculate_stylist_salon_match(uuid)','fn:calculate_stylist_store_match(uuid)','fn:create_notification(uuid,text,text,text,text,uuid)','fn:decline_hiring_process(uuid,text)','fn:delete_stylist_evidence_document(uuid)','fn:get_my_age_disclosure_requests()','fn:get_my_hiring_processes()','fn:handle_new_user()','fn:is_platform_admin()','fn:mark_scout_read(uuid)','fn:register_stylist_evidence_document(text,text,text)','fn:respond_age_disclosure_request(uuid,boolean)','fn:respond_salary_offer(uuid,text,text,text)','fn:respond_scout(uuid,text,text)','fn:save_stylist_match_profile(text,text[],text,integer,integer,integer,integer,integer,integer,integer,integer,numeric,integer,integer,text)','fn:save_stylist_match_profile_v2(text,text[],text,boolean,integer,integer,integer,integer,integer,integer,integer,integer,numeric,integer,integer,text)','fn:save_stylist_preference_profile(stylist_preference_status,integer,jsonb)','fn:save_stylist_profile_v2(text,text,age_band,gender_type,text,text,integer,text,text[],employment_type,job_change_intent,salary_band,jsonb,text,profile_visibility,boolean,text,text[],date,text)','fn:save_stylist_profile_v4(text,text,age_band,gender_type,text,text,integer,text,text[],employment_type,job_change_intent,salary_band,jsonb,text,profile_visibility,boolean,text,text[],date,text,text,date,integer,text)','fn:set_favorite_salon(uuid,boolean)','fn:set_store_interest_v2(uuid,text,boolean)','fn:set_stylist_age_display_mode(text)','fn:set_stylist_birth_date(date)','fn:set_stylist_value_priorities(text[])','fn:stylist_age_yea